const gameTypes = ['Todos','Mata-mata','Mata-mata por equipes','Captura da bandeira','Dominação','Conquista de território','Ataque e defesa','Defesa de base','Escolta','Resgate','Busca e destruição','Recuperação de objeto','Controle de pontos','Missões sequenciais','Múltiplos objetivos','Jogo personalizado']

function OperationCreateModal({onClose}:{onClose:()=>void}) {
  const [step,setStep]=useState(1); const [customGame,setCustomGame]=useState(false); const [customModality,setCustomModality]=useState(false); const [selectedModality,setSelectedModality]=useState(''); const [templateDecision,setTemplateDecision]=useState(''); const [saved,setSaved]=useState('')
  const steps=['Informações','Local','Data','Custos','Regras','Estrutura']
  return <div className="classified-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="classified-modal classified-modal--wide operation-create" role="dialog" aria-modal="true" aria-labelledby="operation-create-title"><button className="classified-modal-close" onClick={onClose} aria-label="Fechar"><X/></button><p className="classified-kicker">ORGANIZADOR · RASCUNHO DEMONSTRATIVO</p><h2 id="operation-create-title">Criar operação</h2><nav className="operation-steps" aria-label="Etapas da operação">{steps.map((label,index)=><button key={label} className={step===index+1?'active':''} onClick={()=>setStep(index+1)}><span>0{index+1}</span>{label}</button>)}</nav><form onSubmit={e=>{e.preventDefault();setSaved('Rascunho demonstrativo revisado. Nenhum dado ou arquivo foi enviado.')}}>
    {step===1&&<><div className="classified-form-row"><label><span>Nome da operação</span><input required maxLength={120}/></label><label><span>Subtítulo</span><input maxLength={120}/></label></div><label><span>Descrição resumida</span><textarea required maxLength={500}/></label><div className="classified-form-row"><label><span>Modalidade da operação</span><select required value={selectedModality} onChange={e=>{setSelectedModality(e.target.value);setCustomModality(e.target.value==='Modalidade personalizada');setTemplateDecision('')}}><option value="">Selecione a modalidade</option>{operationModalities.slice(1).map(item=><option key={item}>{item}</option>)}</select><small>Estilo geral, realismo e conjunto de regras.</small></label><label><span>Tipo de jogo principal</span><select required onChange={e=>setCustomGame(e.target.value==='Jogo personalizado')}><option value="">Selecione o objetivo</option>{gameTypes.slice(1).map(type=><option key={type}>{type}</option>)}</select><small>Objetivo ou dinâmica específica da partida.</small></label></div>{selectedModality&&!customModality&&<div className="operation-template-suggestion"><ShieldCheck/><div><strong>Modelo sugerido: {selectedModality}</strong><p>Deseja carregar o modelo sugerido desta modalidade? Regras já escritas nunca serão substituídas silenciosamente.</p><div><button type="button" onClick={()=>setTemplateDecision('Modelo completo aplicado como sugestão editável.')}>Aplicar modelo</button><button type="button" onClick={()=>setTemplateDecision('Selecione depois quais regras, funções e equipamentos deseja aproveitar.')}>Aplicar parcialmente</button><button type="button" onClick={()=>setTemplateDecision('Modelo ignorado. A configuração continuará vazia.')}>Ignorar</button></div>{templateDecision&&<span>{templateDecision}</span>}</div></div>}{customModality&&<div className="operation-custom"><strong>Modalidade personalizada</strong><div className="classified-form-row classified-form-row--three"><label><span>Nome</span><input required maxLength={100}/></label><label><span>Sigla</span><input required maxLength={20}/></label><label><span>Base utilizada</span><input maxLength={100} placeholder="Ex.: regras 4FUN adaptadas"/></label></div><div className="classified-form-row"><label><span>Nível de realismo</span><select><option>Baixo</option><option>Médio</option><option>Alto</option></select></label><label><span>Respawn e atendimento</span><input required maxLength={200}/></label></div><label><span>Regras, munição, comunicação e equipamentos</span><textarea required maxLength={2500}/></label><label><span>Times, esquadrões, objetivos, penalidades e vitória</span><textarea required maxLength={2500}/></label><div className="classified-form-row"><label><span>PDF explicativo</span><input type="file" accept="application/pdf"/></label><label className="classified-check"><input type="checkbox"/><span>Salvar como modelo privado. Publicação para outros organizadores dependerá de aprovação administrativa.</span></label></div></div>}{customGame&&<div className="operation-custom operation-custom--game"><strong>Tipo de jogo personalizado</strong><div className="classified-form-row"><label><span>Nome do tipo</span><input required maxLength={100}/></label><label><span>Duração e rodadas</span><input required maxLength={100}/></label></div><label><span>Objetivo, pontuação e condição de vitória</span><textarea required maxLength={1500}/></label></div>}<div className="classified-form-row classified-form-row--three"><label><span>Dificuldade</span><select><option>Iniciante</option><option>Intermediária</option><option>Avançada</option></select></label><label><span>Indicada para iniciantes?</span><select required><option>Sim</option><option>Não</option><option>Somente com acompanhamento</option><option>Conforme regras do organizador</option></select></label><label><span>Visibilidade</span><select><option>Pública</option><option>Privada por convite</option></select></label></div></>}
    {step===2&&<><div className="classified-form-row"><label><span>Campo cadastrado</span><select required><option>Campo Bravo Zero</option><option>Distrito 7 Arena</option><option>Vale Sombrio</option><option>Usar local não cadastrado</option></select></label><label><span>Nome do local</span><input required/></label></div><div className="classified-form-row"><BrazilLocationFields namePrefix="operation"/></div><label><span>Instruções de chegada e ponto de encontro</span><textarea maxLength={1000}/></label><label className="classified-check"><input type="checkbox"/><span>Local reservado: ocultar endereço preciso até a aprovação da inscrição.</span></label></>}
    {step===3&&<><div className="classified-form-row classified-form-row--three"><label><span>Data da operação</span><input required type="date"/></label><label><span>Abertura dos portões</span><input required type="time"/></label><label><span>Início</span><input required type="time"/></label></div><div className="classified-form-row classified-form-row--three"><label><span>Check-in</span><input type="time"/></label><label><span>Briefing</span><input type="time"/></label><label><span>Encerramento previsto</span><input required type="time"/></label></div><div className="classified-form-row"><label><span>Início das inscrições</span><input required type="datetime-local"/></label><label><span>Fim das inscrições</span><input required type="datetime-local"/></label></div><p className="operation-form-alert"><ShieldAlert/> Alterações de data exigirão motivo, auditoria e notificação aos inscritos.</p></>}
    {step===4&&<><div className="classified-form-row"><label><span>Participação</span><select><option>Gratuita</option><option>Paga</option></select></label><label><span>Valor individual</span><input type="number" min="0" step="0.01"/></label></div><label><span>Itens inclusos e formas aceitas</span><textarea maxLength={1000}/></label><label><span>Política de cancelamento e reembolso do organizador</span><textarea required maxLength={1500}/></label><p className="operation-form-alert"><ShieldAlert/> O Operador Zero não processa pagamentos, não retém valores e não garante reembolso. Cobrança e recebimento são responsabilidade do organizador.</p></>}
    {step===5&&<><label><span>Regras gerais e de segurança</span><textarea required maxLength={5000}/></label><div className="classified-form-row"><label><span>Limites de FPS/joules</span><textarea required/></label><label><span>Respawn, eliminação e rendição</span><textarea required/></label></div><div className="classified-form-row"><label><span>Documento da operação (PDF)</span><input type="file" accept="application/pdf"/><small>Máximo sugerido: 20 MB. Nenhum arquivo é enviado nesta demonstração.</small></label><label><span>Visibilidade do documento</span><select><option>Público</option><option>Somente inscritos</option><option>Somente comandantes</option><option>Privado da organização</option></select></label></div><label className="classified-check"><input type="checkbox" required/><span>Confirmo que participantes deverão aceitar a versão publicada das regras e aceitar novamente após mudanças relevantes.</span></label></>}
    {step===6&&<><div className="classified-form-row classified-form-row--three"><label><span>Limite de operadores</span><input required type="number" min="2"/></label><label><span>Quantidade de times</span><input required type="number" min="2" max="20"/></label><label><span>Missões planejadas</span><input required type="number" min="1"/></label></div><div className="operation-structure-preview"><div><strong>TIME ALFA</strong><span>Alfa 1 · Assalto</span><span>Alfa 2 · Suporte</span></div><div><strong>TIME BRAVO</strong><span>Bravo 1 · Defesa</span><span>Bravo 2 · Reconhecimento</span></div><div><strong>MISSÕES</strong><span>M-01 · Planejada</span><span>M-02 · Bloqueada</span></div></div><label className="classified-check"><input type="checkbox"/><span>Manter composição de times e missões privadas até o briefing.</span></label></>}
    <div className="operation-form-actions"><button type="button" disabled={step===1} onClick={()=>setStep(step-1)}>Voltar</button>{step<6?<button className="button" type="button" onClick={()=>setStep(step+1)}>Próxima etapa <ArrowRight/></button>:<><button type="button" onClick={()=>setSaved('Rascunho demonstrativo salvo somente nesta tela.')}>Salvar rascunho</button><button className="button" type="submit">Revisar operação <ShieldCheck/></button></>}</div></form>{saved&&<p className="classified-form-notice" role="status"><ShieldCheck/>{saved}</p>}</section></div>
}

function OperationDetailModal({operation,onClose}:{operation:OperationItem;onClose:()=>void}) {
  const [tab,setTab]=useState('Visão geral'); const [joined,setJoined]=useState(false)
  const tabs=['Visão geral','Regras','Missões','Times e esquadrões','Cronograma','Documento','Participantes','Atualizações']
  return <div className="classified-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="classified-modal classified-modal--wide operation-detail" role="dialog" aria-modal="true" aria-labelledby="operation-detail-title"><button className="classified-modal-close" onClick={onClose} aria-label="Fechar"><X/></button><div className="operation-detail-hero"><div><span>{operation.status}</span><strong>{operation.day}</strong><small>{operation.month} · {operation.time}</small></div><div><p className="classified-kicker">{operation.modality} · {operation.type}</p><h2 id="operation-detail-title">{operation.name}</h2><p><MapPin/> {operation.field} · {operation.city} · {operation.organizer}</p></div></div><nav className="operation-detail-tabs" aria-label="Seções da operação">{tabs.map(item=><button className={tab===item?'active':''} onClick={()=>setTab(item)} key={item}>{item}</button>)}</nav>
    {tab==='Visão geral'&&<div className="operation-detail-grid"><div><h3>Operação em múltiplas fases</h3><p>Experiência demonstrativa com objetivos progressivos, equipes organizadas e briefing estruturado. Informações privadas permanecem ocultas até aprovação.</p><div className="wanted-spec-grid"><div><span>Modalidade</span><strong>{operation.modality}</strong></div><div><span>Tipo de jogo</span><strong>{operation.type}</strong></div><div><span>Iniciantes</span><strong>{operation.beginner}</strong></div><div><span>Vagas</span><strong>{operation.registered}/{operation.slots}</strong></div><div><span>Valor</span><strong>{operation.price?operation.price.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'Gratuita'}</strong></div><div><span>Times</span><strong>{operation.teams}</strong></div><div><span>Missões</span><strong>{operation.missions}</strong></div><div><span>Documento</span><strong>{operation.pdf?'Disponível':'Não publicado'}</strong></div></div></div><aside><button className="button" disabled={operation.cancelled||operation.past} onClick={()=>setJoined(true)}>{joined?'Solicitação registrada':'Participar'}</button><button>Compartilhar</button><button>Favoritar</button><button>Denunciar</button></aside></div>}
    {tab==='Regras'&&<div className="operation-info-list"><h3>Regras versão 3</h3><p>Segurança, limites de energia, distância mínima, eliminação, rendição, respawn e conduta.</p><p className="operation-form-alert"><ShieldAlert/> Mudanças relevantes exigem novo aceite dos participantes.</p></div>}
    {tab==='Missões'&&<div className="operation-mission-list">{['M-01 Estabelecer perímetro','M-02 Recuperar inteligência','M-03 Defender ponto de extração'].map((m,i)=><div key={m}><span>0{i+1}</span><strong>{m}</strong><small>{i===0?'Disponível':'Bloqueada · libera após missão anterior'}</small></div>)}</div>}
    {tab==='Times e esquadrões'&&<div className="operation-structure-preview"><div><strong>TIME ALFA · 34/40</strong><span>Alfa 1 · Assalto</span><span>Alfa 2 · Suporte</span></div><div><strong>TIME BRAVO · 34/40</strong><span>Bravo 1 · Defesa</span><span>Bravo 2 · Reconhecimento</span></div><div><strong>COMANDO</strong><span>Comandantes confirmados</span><span>Canais liberados no briefing</span></div></div>}
    {tab==='Cronograma'&&<div className="operation-mission-list">{['07:00 · Portões e check-in','07:40 · Briefing obrigatório','08:00 · Início da operação','13:00 · Encerramento previsto'].map((item,i)=><div key={item}><span>0{i+1}</span><strong>{item}</strong></div>)}</div>}
    {tab==='Documento'&&<div className="operation-document"><Package/><h3>Documento da operação · versão 2</h3><p>PDF demonstrativo com briefing, mapas, missões e regras. Acesso público nesta operação.</p><button disabled={!operation.pdf}>Abrir documento</button></div>}
    {tab==='Participantes'&&<div className="operation-info-list"><h3>{operation.registered} inscritos</h3><p>Lista pública minimizada. Dados privados, pagamento e check-in são visíveis somente conforme permissão.</p><div className="operation-participants"><span>NOMAD · Confirmado</span><span>RAVEN · Aprovada</span><span>ATLAS · Lista de espera</span></div></div>}
    {tab==='Atualizações'&&<div className="operation-mission-list"><div><span>01</span><strong>Novo documento publicado</strong><small>Hoje · leitura recomendada</small></div><div><span>02</span><strong>Horário do briefing confirmado</strong><small>Ontem · alteração importante</small></div></div>}
  </section></div>
}

function OperationsPage() {
  const [tab,setTab]=useState('Próximas'); const [filters,setFilters]=useState(false); const [modality,setModality]=useState('Todas'); const [type,setType]=useState('Todos'); const [city,setCity]=useState('Todas'); const [cost,setCost]=useState('Todas'); const [create,setCreate]=useState(false); const [detail,setDetail]=useState<OperationItem|null>(null)
  const tabs=['Próximas','Inscrições abertas','Hoje','Em andamento','Minhas operações','Operações realizadas','Canceladas']
  const visible=operationCatalog.filter(op=>{const tabMatch=tab==='Operações realizadas'?op.past:tab==='Canceladas'?op.cancelled:tab==='Inscrições abertas'?op.status.includes('Inscrições')||op.status==='Últimas vagas':tab==='Minhas operações'?op.id===1:tab==='Hoje'?false:tab==='Em andamento'?op.status==='Em andamento':!op.past&&!op.cancelled; return tabMatch&&(modality==='Todas'||op.modality===modality)&&(type==='Todos'||op.type===type)&&(city==='Todas'||op.city===city)&&(cost==='Todas'||(cost==='Gratuita'?op.price===0:op.price>0))}).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)||a.city.localeCompare(b.city)||a.name.localeCompare(b.name))
  return <main className="operations-page"><header className="operations-heading"><div><p className="classified-kicker">AGENDA E GESTÃO OPERACIONAL</p><h1>Operações<br/><em>em campo.</em></h1><span>Próximas operações ordenadas pela data mais próxima.</span></div><button className="button" onClick={()=>setCreate(true)}><Plus/> Criar operação</button></header><section className="operation-role-note"><ShieldCheck/><p><strong>Modo organizador demonstrativo.</strong> Em produção, criar, publicar e administrar dependerá de permissões validadas no backend.</p></section><nav className="operations-tabs" aria-label="Filtros de situação">{tabs.map(item=><button className={tab===item?'active':''} onClick={()=>setTab(item)} key={item}>{item}</button>)}</nav><div className="operations-toolbar"><label><Search/><input aria-label="Buscar operações" placeholder="Buscar por modalidade, tipo, operação, campo ou cidade"/></label><button className={filters?'active':''} onClick={()=>setFilters(!filters)}><SlidersHorizontal/> Filtros</button><select aria-label="Ordenar operações"><option>Data mais próxima</option><option>Menor valor</option><option>Maior valor</option><option>Mais vagas</option></select></div>{filters&&<section className="operations-filter-panel operations-filter-panel--modality"><label><span>Modalidade</span><select value={modality} onChange={e=>setModality(e.target.value)}>{operationModalities.map(item=><option key={item}>{item}</option>)}</select></label><label><span>Tipo de jogo</span><select value={type} onChange={e=>setType(e.target.value)}>{gameTypes.map(item=><option key={item}>{item}</option>)}</select></label><label><span>Cidade</span><select value={city} onChange={e=>setCity(e.target.value)}><option>Todas</option>{[...new Set(operationCatalog.map(op=>op.city))].map(item=><option key={item}>{item}</option>)}</select></label><label><span>Participação</span><select value={cost} onChange={e=>setCost(e.target.value)}><option>Todas</option><option>Gratuita</option><option>Paga</option></select></label><label><span>Iniciantes</span><select><option>Qualquer indicação</option><option>Sim</option><option>Não</option><option>Com acompanhamento</option></select></label></section>}<section className="operations-results"><div className="classified-results-head"><div><p>ORDENAÇÃO PADRÃO · DATA MAIS PRÓXIMA</p><h2>{tab}</h2></div><span>{visible.length} operações</span></div><div className="operations-grid">{visible.map((op,index)=><article className="operation-card" key={op.id}><div className="operation-card-media"><img src="/operador-zero-identity.jpeg" alt="Imagem demonstrativa da operação"/><span>{index===0&&tab==='Próximas'?'EM 5 DIAS':op.status}</span><div><strong>{op.day}</strong><small>{op.month}<br/>{op.time}</small></div></div><div className="operation-card-content"><p>{op.modality} · {op.type}</p><h3>{op.name}</h3><span><MapPin/>{op.field} · {op.city}</span><div className="operation-card-stats"><div><small>VALOR</small><strong>{op.price?op.price.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'GRÁTIS'}</strong></div><div><small>VAGAS</small><strong>{op.registered}/{op.slots}</strong></div><div><small>ESTRUTURA</small><strong>{op.teams} times · {op.missions} missões</strong></div></div><div className="operation-card-badges"><span>{op.status}</span><span>Iniciantes: {op.beginner}</span>{op.pdf&&<span>PDF disponível</span>}{op.custom&&<span>Jogo personalizado</span>}</div><small>Organização: {op.organizer} · {op.private?'Privada':'Pública'}</small><footer><button onClick={()=>setDetail(op)}>Ver operação</button><button className="button" disabled={op.past||op.cancelled}>Participar</button></footer></div></article>)}</div>{!visible.length&&<div className="classified-empty"><CalendarDays/><h3>Nenhuma operação nesta situação</h3><p>Selecione outra aba ou ajuste os filtros.</p></div>}</section><p className="dashboard-disclaimer"><ShieldCheck/> Dados, documentos, inscrições e operações são demonstrativos e não são persistidos.</p>{create&&<OperationCreateModal onClose={()=>setCreate(false)}/>} {detail&&<OperationDetailModal operation={detail} onClose={()=>setDetail(null)}/>}</main>
}

