function AchievementsPage() {
  const [query,setQuery]=useState(''); const [status,setStatus]=useState('Todas'); const [category,setCategory]=useState('Todas'); const [selected,setSelected]=useState<Achievement|null>(null); const [featured,setFeatured]=useState<number[]>([1,2,3]); const [admin,setAdmin]=useState(false)
  const visible=achievements.filter(item=>(!query||item.name.toLowerCase().includes(query.toLowerCase()))&&(category==='Todas'||item.category===category)&&(status==='Todas'||status===item.status||status===item.rarity||(status==='Secretas'&&item.secret)))
  const unlocked=achievements.filter(item=>item.status==='Desbloqueada').length; const feature=(id:number)=>setFeatured(current=>current.includes(id)?current.filter(item=>item!==id):current.length<3?[...current,id]:[current[1],current[2],id])
  return <main className="achievements-page"><header className="achievements-heading"><div><p className="achievement-kicker">COLEÇÃO DO OPERADOR · TEMPORADA 2026</p><h1>Conquistas<br/><em>e medalhas.</em></h1><span>Reconhecimento equilibrado para participação, função, equipe, honestidade e desempenho confirmado.</span></div><button onClick={()=>setAdmin(true)}><Settings/> Administrar catálogo</button></header><section className="achievement-progress-hero"><div><small>PROGRESSO GERAL</small><strong>{unlocked}<span>/100</span></strong><p>conquistas desbloqueadas</p></div><div><span>{unlocked}% concluído</span><i><b style={{width:`${unlocked}%`}}/></i><p>Próxima: <strong>Operador Ofensivo</strong> · 40 de 50 eliminações</p></div><div><small>EM DESTAQUE NO PERFIL</small><div>{featured.map(id=><span key={id}><Medal/>{achievements[id-1].name}</span>)}</div></div></section><section className="achievement-recent"><header><div><p className="achievement-kicker">DESBLOQUEADA RECENTEMENTE</p><h2>Veterano de Campo</h2><span>10 operações homologadas · Rara</span></div><div className="achievement-recent-medal"><Trophy/></div><button onClick={()=>setSelected(achievements[2])}>Ver conquista <ArrowRight/></button></header></section><div className="achievement-layout"><aside><label className="achievement-search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar conquista" aria-label="Buscar conquista"/></label><div><span>STATUS E RARIDADE</span>{['Todas','Desbloqueada','Em progresso','Bloqueada','Comum','Incomum','Rara','Épica','Lendária','Secretas'].map(item=><button className={status===item?'active':''} onClick={()=>setStatus(item)} key={item}>{item}<small>{item==='Todas'?100:''}</small></button>)}</div><label><span>CATEGORIA</span><select value={category} onChange={e=>setCategory(e.target.value)}>{achievementCategories.map(item=><option key={item}>{item}</option>)}</select></label><label><span>POSIÇÃO</span><select><option>Todas as posições</option><option>Comando</option><option>Assalto</option><option>Defesa</option><option>Médico</option></select></label><label><span>TEMPORADA</span><select><option>Temporada 2026</option><option>Histórico completo</option></select></label></aside><section><header className="achievement-results-head"><div><p>{visible.length} CONQUISTAS</p><h2>{category}</h2></div><span>Ordenar: progresso</span></header><div className="achievement-grid">{visible.map(item=>{const percentage=Math.min(100,Math.round(item.current/item.target*100));return <button className={`achievement-card ${item.status==='Desbloqueada'?'unlocked':''}`} onClick={()=>setSelected(item)} key={item.id}><div className={`achievement-medal rarity-${item.rarity.toLowerCase()}`}>{item.secret&&item.status!=='Desbloqueada'?<LockKeyhole/>:<Medal/>}</div><span>{item.rarity} · {item.type}</span><h3>{item.secret&&item.status!=='Desbloqueada'?'Conquista secreta':item.name}</h3><p>{item.secret&&item.status!=='Desbloqueada'?'Condição oculta até o desbloqueio.':item.description}</p><div className="achievement-card-progress"><i><b style={{width:`${percentage}%`}}/></i><span>{item.current} / {item.target}</span></div><footer><small>{item.category}</small><em>{item.status}</em></footer></button>})}</div></section></div><p className="dashboard-disclaimer"><ShieldCheck/> Catálogo demonstrativo com 100 definições. Progresso, concessões, destaques e compartilhamentos não são persistidos.</p>{selected&&<AchievementDetail achievement={selected} onClose={()=>setSelected(null)} onFeature={()=>feature(selected.id)}/>} {admin&&<AchievementAdmin onClose={()=>setAdmin(false)}/>}</main>
}
type OperatorTab = 'Visão geral'|'Equipamentos'|'Equipe'|'Ranking'|'Conquistas'|'Operações'|'Reputação'|'Privacidade'|'Configurações da conta'
const operatorTabs:OperatorTab[]=['Visão geral','Equipamentos','Equipe','Ranking','Conquistas','Operações','Reputação','Privacidade','Configurações da conta']
const privacyOptions=['Somente eu','Minha equipe','Organizadores das minhas operações','Usuários conectados','Público']
const recentOperatorOperations=[
  {date:'12 JUL',name:'Black Forest',place:'Curitiba, PR',role:'Reconhecimento',status:'Homologada'},
  {date:'28 JUN',name:'Distrito 7',place:'Colombo, PR',role:'Assalto',status:'Homologada'},
  {date:'14 JUN',name:'Vale Sombrio',place:'Ponta Grossa, PR',role:'Reconhecimento',status:'Confirmada'},
  {date:'31 MAI',name:'Ponto de Ruptura',place:'Araucária, PR',role:'Defesa',status:'Homologada'},
  {date:'17 MAI',name:'Linha Vermelha',place:'Curitiba, PR',role:'Reconhecimento',status:'Homologada'},
]

function OperatorModal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){
  return <div className="ranking-modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="ranking-modal operator-modal" role="dialog" aria-modal="true" aria-label={title}><button className="ranking-modal-close" onClick={onClose} aria-label="Fechar"><X/></button>{children}</section></div>
}
function OperatorProfilePage({onViewAll}:{onViewAll:()=>void}) {
  const [tab,setTab]=useState<OperatorTab>('Visão geral'); const [modal,setModal]=useState<'edit'|'privacy'|'preview'|'account'|null>(null); const [preset,setPreset]=useState('Equilibrado'); const [previewRole,setPreviewRole]=useState('Visitante'); const [notice,setNotice]=useState('')
  const privacyFields=['Nome real','Nick / callsign','Foto','Cidade','Estado','Idade','Data de nascimento','Equipe ativa','Histórico de equipes','Posição preferida','Equipamentos','Ranking','K/D confirmado','Operações','Conquistas','Reputação','Disponível para equipe','Redes sociais','Última atividade']
  const renderOverview=()=> <div className="operator-overview-grid"><section className="operator-block operator-intro"><p className="operator-kicker">IDENTIDADE DE JOGO</p><h2>Disciplina antes da velocidade.</h2><p>Operador de reconhecimento, focado em leitura de terreno, comunicação e apoio à equipe. Perfil ativo desde 2024.</p><dl><div><dt>Posição preferida</dt><dd>Reconhecimento</dd></div><div><dt>Modalidades</dt><dd>Milsim · Objetivos · CQB</dd></div><div><dt>Frequência</dt><dd>2 vezes por mês</dd></div><div><dt>Experiência</dt><dd>Intermediária</dd></div></dl></section><section className="operator-block operator-last"><p className="operator-kicker">ÚLTIMA OPERAÇÃO</p><span>12 JUL · HOMOLOGADA</span><h2>Black Forest</h2><p><MapPin/> Curitiba, PR · Reconhecimento</p><div><b>92,4</b><small>índice ajustado de função</small></div></section><section className="operator-block operator-equipment-preview"><header><p className="operator-kicker">MEU EQUIPAMENTO</p><button onClick={()=>setTab('Equipamentos')}>Ver inventário <ArrowRight/></button></header><h2>M4 URGI · AEG</h2><p>Plataforma principal · Ranger Green</p><span>Válido para airsoft · visível para usuários conectados</span></section><section className="operator-block operator-ops-preview"><header><p className="operator-kicker">ATIVIDADE RECENTE</p><button onClick={()=>setTab('Operações')}>Ver operações <ArrowRight/></button></header>{recentOperatorOperations.slice(0,3).map(item=><article key={item.name}><b>{item.date}</b><span><strong>{item.name}</strong><small>{item.place} · {item.role}</small></span><em>{item.status}</em></article>)}</section><section className="operator-block operator-featured"><header><p className="operator-kicker">CONQUISTAS EM DESTAQUE</p><button onClick={onViewAll}>Ver todas <ArrowRight/></button></header><div>{achievements.slice(0,3).map(item=><article key={item.id}><span className={`achievement-medal rarity-${item.rarity.toLowerCase()}`}><Medal/></span><small>{item.rarity}</small><strong>{item.name}</strong></article>)}</div></section></div>
  const renderContent=()=>{
    if(tab==='Visão geral') return renderOverview()
    if(tab==='Equipamentos') return <section className="operator-section"><header><div><p className="operator-kicker">AIRSOFT · INVENTÁRIO VISÍVEL</p><h2>Meu equipamento</h2></div><button className="button" onClick={()=>setModal('edit')}><Plus/> Adicionar equipamento</button></header><div className="operator-equipment-list">{[['Principal','M4 URGI','AEG','E&C · elétrico · Ranger Green'],['Secundário','G17 Gen 4','GBB','WE · gás · Preto'],['Suporte','Baofeng UV-5R','Rádio','Comunicação de equipe']].map(item=><article key={item[1]}><Target/><div><small>{item[0]} · {item[2]}</small><h3>{item[1]}</h3><p>{item[3]}</p></div><span>Usuários conectados</span></article>)}</div><div className="operator-safety-note"><ShieldAlert/><p><strong>Somente equipamentos destinados ao airsoft.</strong> Não publique armas de fogo reais, conversões ou modificações ilegais. Fotos e URLs passam por validação no serviço definitivo.</p></div></section>
    if(tab==='Equipe') return <section className="operator-section"><header><div><p className="operator-kicker">VÍNCULO ATIVO</p><h2>Valkyrie Ops</h2><span>Integrante desde março de 2025 · Curitiba, PR</span></div><button>Ver equipe <ArrowRight/></button></header><div className="operator-team-grid"><article><Users/><strong>Reconhecimento</strong><span>Posição atual</span></article><article><ShieldCheck/><strong>Integrante</strong><span>Status confirmado</span></article><article><CalendarDays/><strong>18 operações</strong><span>Com a equipe</span></article></div><div className="operator-recruitment"><div><p className="operator-kicker">RECRUTAMENTO</p><h3>Integrante de equipe</h3><p>Convites externos estão desativados enquanto existir um vínculo ativo.</p></div><label><span>Status</span><select defaultValue="Integrante de equipe"><option>Integrante de equipe</option><option>Disponível para equipe</option><option>Aberto a convites</option><option>Não disponível</option></select></label></div></section>
    if(tab==='Ranking') return <section className="operator-section"><header><div><p className="operator-kicker">TEMPORADA 2026</p><h2>Desempenho consolidado</h2><span>Comparação equilibrada por participação, função e confirmação.</span></div></header><div className="operator-ranking-grid">{[['#128','Geral','↑ 14'],['#08','Municipal','↑ 2'],['#42','Estadual','—'],['#19','Reconhecimento','↑ 4'],['1.840','Pontuação','temporada'],['92,4','Índice de função','ajustado']].map(item=><article key={item[1]}><small>{item[1]}</small><strong>{item[0]}</strong><span>{item[2]}</span></article>)}</div><div className="operator-trust-row"><span><b>11</b> operações válidas</span><span><b>2,1</b> K/D confirmado</span><span><b>88%</b> eventos confirmados</span><span><b>2026</b> temporada atual</span></div><p className="operator-safety-note"><Trophy/> K/D é informativo e nunca aparece isolado: função, objetivos, equipe e confiabilidade compõem o ranking.</p></section>
    if(tab==='Conquistas') return <section className="operator-section"><header><div><p className="operator-kicker">4 DE 100 DESBLOQUEADAS</p><h2>Conquistas em destaque</h2></div><button onClick={onViewAll}>Ver todas <ArrowRight/></button></header><div className="operator-featured-large">{achievements.slice(0,3).map(item=><article key={item.id}><span className={`achievement-medal rarity-${item.rarity.toLowerCase()}`}><Medal/></span><small>{item.rarity} · {item.category}</small><h3>{item.name}</h3><p>{item.description}</p></article>)}</div></section>
    if(tab==='Operações') return <section className="operator-section"><header><div><p className="operator-kicker">HISTÓRICO COMPARTILHADO</p><h2>Operações recentes</h2><span>Até cinco atividades são exibidas no perfil, conforme a privacidade.</span></div></header><div className="operator-operation-list">{recentOperatorOperations.map(item=><article key={item.name}><b>{item.date}</b><span><strong>{item.name}</strong><small>{item.place} · {item.role}</small></span><em>{item.status}</em></article>)}</div></section>
    if(tab==='Reputação') return <section className="operator-section"><header><div><p className="operator-kicker">INDICADOR AGREGADO</p><h2>Reputação confiável</h2><span>Resultado mínimo agregado, sem revelar autores, comentários ou operações.</span></div></header><div className="operator-reputation"><strong>86</strong><span>/100</span><i><b style={{width:'86%'}}/></i><p>Base suficiente · comportamento, compromisso, confirmações e convivência.</p></div><div className="operator-safety-note"><LockKeyhole/><p>Votos isolados, amostras pequenas, autoria e comentários nunca são expostos. O detalhamento permanece protegido contra retaliação.</p></div></section>
    if(tab==='Privacidade') return <section className="operator-section"><header><div><p className="operator-kicker">CONTROLE POR CAMPO</p><h2>Privacidade do perfil</h2><span>O nome real começa privado. A decisão final deve ser aplicada no servidor.</span></div><button className="button" onClick={()=>setModal('privacy')}><SlidersHorizontal/> Aplicar predefinição</button></header><div className="operator-privacy-list">{privacyFields.map((field,index)=><label key={field}><span>{field}{field==='Nome real'&&<em> padrão seguro</em>}</span><select defaultValue={index===0||index===5||index===6?'Somente eu':index>15?'Usuários conectados':'Público'}>{privacyOptions.map(option=><option key={option}>{option}</option>)}</select></label>)}</div></section>
    return <section className="operator-section"><header><div><p className="operator-kicker">CONTA E SEGURANÇA</p><h2>Configurações da conta</h2><span>Ações sensíveis exigem senha novamente e, quando ativo, MFA.</span></div><button className="button" onClick={()=>setModal('account')}><Settings/> Abrir central segura</button></header><div className="operator-account-grid">{[['Senha e acesso','Atualizada há 42 dias','Alterar senha'],['E-mail','no•••@exemplo.com.br','Verificar e alterar'],['Autenticação em dois fatores','Ainda não configurada','Ativar MFA'],['Sessões ativas','2 dispositivos reconhecidos','Gerenciar sessões'],['Dados da conta','Download disponível por solicitação','Solicitar arquivo'],['Exclusão da conta','Período de confirmação obrigatório','Iniciar processo']].map(item=><article key={item[0]}><div><strong>{item[0]}</strong><span>{item[1]}</span></div><button onClick={()=>setModal('account')}>{item[2]} <ArrowRight/></button></article>)}</div></section>
  }
  return <main className="operator-profile-page"><header className="operator-profile-hero"><div className="operator-avatar-wrap"><span className="operator-profile-avatar">N</span><i><ShieldCheck/></i></div><div className="operator-profile-identity"><p className="operator-kicker">MEU OPERADOR · PERFIL VERIFICADO</p><h1>NOMAD</h1><div><span>@nomad.pr</span><span>Nome real privado</span></div><p><MapPin/> Curitiba, PR <b>·</b> Valkyrie Ops <b>·</b> Reconhecimento</p><span className="operator-status">INTEGRANTE DE EQUIPE</span></div><div className="operator-profile-actions"><button onClick={()=>setModal('preview')}><Eye/> Visualizar como os outros veem</button><button onClick={()=>setModal('privacy')}><LockKeyhole/> Configurar privacidade</button><button className="button" onClick={()=>setModal('edit')}><Settings/> Editar perfil</button></div></header><section className="operator-profile-stats">{[['#128','Ranking geral'],['#08','Ranking municipal'],['86/100','Reputação agregada'],['11','Operações válidas']].map(item=><div key={item[1]}><strong>{item[0]}</strong><span>{item[1]}</span></div>)}</section><nav className="operator-tabs" aria-label="Seções do perfil">{operatorTabs.map(item=><button className={tab===item?'active':''} onClick={()=>setTab(item)} key={item}>{item}</button>)}</nav>{renderContent()}<p className="dashboard-disclaimer"><ShieldCheck/> Demonstração local: alterações e controles desta tela não são persistidos. Privacidade efetiva requer filtragem no backend.</p>
  {modal==='edit'&&<OperatorModal title="Editar perfil" onClose={()=>setModal(null)}><p className="operator-kicker">EDIÇÃO DO OPERADOR</p><h2>Identidade e preferências</h2><div className="operator-form-grid"><label><span>Nome de exibição</span><input defaultValue="Nomad" maxLength={80}/></label><label><span>Nick / callsign</span><input defaultValue="NOMAD" maxLength={40}/></label><label><span>Nome de usuário único</span><input defaultValue="nomad.pr" pattern="[A-Za-z0-9._-]+" maxLength={30}/><small>Sem espaços · alteração disponível em 18 dias</small></label><BrazilLocationFields defaultState="PR" defaultCity="Curitiba" namePrefix="operator"/><label><span>Posição preferida</span><select defaultValue="Reconhecimento"><option>Reconhecimento</option><option>Assalto</option><option>Defesa</option><option>Médico</option><option>Comando</option></select></label><label><span>Equipamento principal</span><input defaultValue="M4 URGI" maxLength={80}/></label><label><span>Categoria</span><select><option>AEG</option><option>GBB</option><option>GBBR</option><option>HPA</option><option>Mola</option><option>Sniper</option><option>DMR</option><option>Suporte</option></select></label><label className="wide"><span>Bio</span><textarea defaultValue="Disciplina, comunicação e leitura de terreno." maxLength={500}/></label><label className="wide"><span>Rede social</span><input type="url" placeholder="https://" maxLength={240}/></label></div><div className="operator-safety-note"><ShieldAlert/><p>URLs, texto e imagens precisam de validação no backend. Não informe endereço exato, CPF, telefone ou dados sensíveis.</p></div>{notice&&<p className="ranking-demo-notice">{notice}</p>}<footer><button onClick={()=>setModal(null)}>Cancelar</button><button className="button" onClick={()=>setNotice('Alterações validadas somente nesta demonstração; nenhum dado foi salvo.')}>Revisar alterações</button></footer></OperatorModal>}
  {modal==='privacy'&&<OperatorModal title="Predefinições de privacidade" onClose={()=>setModal(null)}><p className="operator-kicker">PRIVACIDADE POR PADRÃO</p><h2>Escolha um ponto de partida</h2><div className="operator-preset-grid">{[['Público','Maior descoberta, mantendo nome real e dados sensíveis privados.'],['Equilibrado','Equipe e atividade visíveis para usuários conectados.'],['Privado','Quase tudo limitado à sua equipe ou somente a você.'],['Personalizado','Ajuste campo por campo na aba Privacidade.']].map(item=><button className={preset===item[0]?'active':''} onClick={()=>setPreset(item[0])} key={item[0]}><strong>{item[0]}</strong><span>{item[1]}</span></button>)}</div><div className="operator-safety-note"><LockKeyhole/><p>Nome real, data de nascimento e última atividade não se tornam públicos automaticamente em nenhuma predefinição.</p></div><footer><button onClick={()=>setModal(null)}>Cancelar</button><button className="button" onClick={()=>{setNotice('Predefinição aplicada apenas nesta sessão.');setModal(null);setTab('Privacidade')}}>Aplicar {preset}</button></footer></OperatorModal>}
  {modal==='preview'&&<OperatorModal title="Pré-visualização pública" onClose={()=>setModal(null)}><p className="operator-kicker">VISUALIZAÇÃO SEGURA</p><h2>Como seu perfil aparece</h2><label className="operator-preview-role"><span>Visualizar como</span><select value={previewRole} onChange={e=>setPreviewRole(e.target.value)}><option>Visitante</option><option>Usuário conectado</option><option>Integrante da equipe</option><option>Organizador da operação</option><option>Administrador</option></select></label><div className="operator-public-preview"><span className="operator-profile-avatar">N</span><div><small>PERFIL PÚBLICO</small><h3>NOMAD</h3><p>@nomad.pr · {previewRole==='Visitante'?'Paraná':'Curitiba, PR'}</p><span>Valkyrie Ops · Reconhecimento</span></div></div><div className="operator-preview-hidden"><LockKeyhole/><span>Oculto nesta visão: nome real, data de nascimento, contato, endereço exato, sessões e dados da conta.</span></div></OperatorModal>}
  {modal==='account'&&<OperatorModal title="Central segura da conta" onClose={()=>setModal(null)}><p className="operator-kicker">REAUTENTICAÇÃO OBRIGATÓRIA</p><h2>Confirme sua identidade</h2><p className="ranking-modal-lead">Antes de alterar e-mail, senha, username, MFA, sessões ou excluir a conta, o serviço definitivo deve validar senha e segundo fator.</p><div className="operator-form-grid"><label className="wide"><span>Senha atual</span><input type="password" placeholder="Não use sua senha real nesta demonstração" autoComplete="current-password"/></label><label className="wide"><span>Código MFA</span><input inputMode="numeric" placeholder="000 000" maxLength={6}/></label></div><div className="operator-safety-note"><ShieldCheck/><p>Códigos de recuperação devem ser exibidos uma única vez, armazenados com hash e nunca registrados em logs.</p></div>{notice&&<p className="ranking-demo-notice">{notice}</p>}<footer><button onClick={()=>setModal(null)}>Cancelar</button><button className="button" onClick={()=>setNotice('Reautenticação simulada. Nenhuma credencial foi enviada.')}>Confirmar identidade</button></footer></OperatorModal>}</main>
}

const globalSearchGroups=[
  {title:'Operadores',items:[{name:'RAVEN',meta:'@raven.pr · Echo Squad · Curitiba, PR',badge:'Assalto · #21'},{name:'GHOST',meta:'@ghost43 · Lince Tático · Colombo, PR',badge:'Reconhecimento · #34'}]},
  {title:'Equipes',items:[{name:'Valkyrie Ops',meta:'Curitiba, PR · 18 integrantes',badge:'Recrutando'},{name:'Sentinelas PR',meta:'São José dos Pinhais, PR · 12 integrantes',badge:'Verificada'}]},
  {title:'Operações',items:[{name:'Operação Linha de Frente',meta:'26 jul · Colombo, PR',badge:'18 vagas'},{name:'Cerco ao Distrito 7',meta:'02 ago · Curitiba, PR',badge:'CQB'}]},
  {title:'Comunidade',items:[{name:'O que levar para a primeira operação?',meta:'Iniciantes · RAVEN · Curitiba, PR',badge:'31 comentários'},{name:'Black Forest: comunicação venceu velocidade',meta:'Relatos de operações · ATLAS',badge:'64 úteis'}]},
  {title:'Campos e campeonatos',items:[{name:'Campo Bravo Zero',meta:'Colombo, PR',badge:'Campo verificado'},{name:'Copa Sul Milsim',meta:'Paraná · temporada 2026',badge:'Campeonato'}]},
]
function GlobalSearch({onOpenOperator}:{onOpenOperator:()=>void}){
  const [query,setQuery]=useState(''); const normalized=query.trim().toLowerCase(); const groups=globalSearchGroups.map(group=>({...group,items:group.items.filter(item=>`${item.name} ${item.meta} ${item.badge}`.toLowerCase().includes(normalized))})).filter(group=>group.items.length)
  return <div className="global-search"><div className="app-search"><Search/><input aria-label="Busca global" value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar operadores, equipes, operações..." autoComplete="off"/>{query&&<button onClick={()=>setQuery('')} aria-label="Limpar busca"><X/></button>}</div>{normalized.length>=2&&<section className="global-search-results" aria-label="Resultados da busca">{groups.length?groups.map(group=><div key={group.title}><h2>{group.title}</h2>{group.items.map(item=><button key={item.name} onClick={()=>{if(group.title==='Operadores')onOpenOperator();setQuery('')}}><span><strong>{item.name}</strong><small>{item.meta}</small></span><em>{item.badge}</em><ArrowRight/></button>)}</div>):<p>Nenhum resultado público encontrado. Tente nick, cidade, equipe, posição ou modalidade.</p>}<footer><ShieldCheck/> Resultados respeitam a visibilidade do perfil. E-mail, telefone, CPF e endereço nunca são pesquisáveis.</footer></section>}</div>
}

function Dashboard({ onLogout }: { onLogout: () => void }) {
  const [profileOpen, setProfileOpen] = useState(false)
  const [activeView, setActiveView] = useState('Visão geral')
  return <div className="app-shell">
    <aside className="app-sidebar">
      <Brand compact/>
      <nav aria-label="Navegação do operador">{dashboardNav.map(({ label, icon: Icon }) => <button onClick={() => setActiveView(label)} className={activeView === label ? 'active' : ''} key={label}><Icon/><span>{label}</span>{activeView === label && <i/>}</button>)}</nav>
      <div className="sidebar-footer"><button><Settings/><span>Configurações</span></button><p>Operador Zero <b>beta</b><br/>v0.1 demonstração</p></div>
    </aside>
    <div className="app-main">
      <header className="app-topbar">
        <GlobalSearch onOpenOperator={()=>setActiveView('Meu Operador')}/>
        <div className="demo-badge"><span/> Modo demonstração</div>
        <button className="notification-button" aria-label="Notificações"><Bell/><i>3</i></button>
        <div className="profile-control"><button onClick={() => setProfileOpen(!profileOpen)} aria-expanded={profileOpen}><span className="profile-avatar">N</span><span><b>NOMAD</b><small>Valkyrie Ops</small></span><ChevronDown/></button>{profileOpen && <div className="profile-menu"><p>Operador demonstrativo</p><button onClick={onLogout}><LogOut/> Sair do modo demonstração</button></div>}</div>
      </header>
      {activeView === 'Classificados' ? <Classifieds/> : activeView === 'Comunidade' ? <CommunityPage/> : activeView === 'Financeiro' ? <FinancialPage/> : activeView === 'Operações' ? <OperationsPage/> : activeView === 'Minha equipe' ? <TeamPage/> : activeView === 'Rankings' ? <RankingPage/> : activeView === 'Conquistas' ? <AchievementsPage/> : activeView === 'Meu Operador' ? <OperatorProfilePage onViewAll={()=>setActiveView('Conquistas')}/> : <main className="dashboard">
        <section className="dashboard-welcome"><div><p>DOMINGO, 20 DE JULHO</p><h1>Olá, <em>NOMAD.</em></h1><span>Seu próximo compromisso é em 6 dias.</span></div><button className="button">Encontrar operação <ArrowRight/></button></section>

        <section className="operator-strip" aria-label="Resumo do operador">
          <div className="operator-identity"><span className="operator-avatar">N</span><div><small>OPERADOR VERIFICADO</small><h2>NOMAD</h2><p>Valkyrie Ops · Curitiba, PR</p></div></div>
          <div><small>RANKING MUNICIPAL</small><strong>#08</strong><span className="positive">↑ 2 posições</span></div>
          <div><small>RANKING ESTADUAL</small><strong>#42</strong><span>Paraná</span></div>
          <div><small>PONTUAÇÃO</small><strong>1.840</strong><span>Temporada 2026</span></div>
          <div className="reputation"><small>REPUTAÇÃO</small><strong>Confiável</strong><span><i style={{width:'86%'}}/></span><em>86 / 100</em></div>
        </section>

        <SponsoredHighlights onSponsor={()=>setActiveView('Financeiro')}/>

        <div className="dashboard-grid">
          <section className="next-operation">
            <div className="dash-section-title"><div><p>PRÓXIMO COMPROMISSO</p><h2>Sua operação</h2></div><button>Ver detalhes <ArrowRight/></button></div>
            <div className="operation-feature"><div className="operation-image"><span>CONFIRMADO</span></div><div className="operation-info"><div className="feature-date"><strong>26</strong><span>JUL<br/>2026</span></div><div><small>DOMINAÇÃO · OPERAÇÃO PÚBLICA</small><h3>Operação Linha de Frente</h3><p><MapPin/> Campo Bravo Zero · Colombo, PR</p><p><CalendarDays/> Apresentação 07:00 · Início 08:00</p></div></div><div className="operation-check"><ShieldCheck/><span>Presença confirmada</span><small>Check-in disponível no local</small></div></div>
          </section>

          <aside className="pending-panel"><div className="dash-section-title"><div><p>ATENÇÃO</p><h2>Pendências</h2></div><span className="count-badge">2</span></div><div className="pending-item"><span>01</span><div><b>Convite de equipe</b><p>Sentinelas PR convidou você.</p></div><button>Revisar</button></div><div className="pending-item"><span>02</span><div><b>Validar desempenho</b><p>Operação Black Forest aguarda confirmação.</p></div><button>Revisar</button></div></aside>
        </div>

        <div className="dashboard-grid dashboard-grid--bottom">
          <section className="performance"><div className="dash-section-title"><div><p>ÚLTIMAS 6 OPERAÇÕES</p><h2>Evolução recente</h2></div><span className="positive"><TrendingUp/> +12,4%</span></div><div className="chart-area"><div className="chart-scale"><span>500</span><span>400</span><span>300</span><span>200</span></div><svg viewBox="0 0 620 180" role="img" aria-label="Evolução de pontuação nas últimas seis operações"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#c9cb73" stopOpacity=".28"/><stop offset="1" stopColor="#c9cb73" stopOpacity="0"/></linearGradient></defs><path className="chart-fill" d="M0 145 L120 120 L240 132 L360 80 L480 92 L620 30 L620 180 L0 180 Z"/><path className="chart-line" d="M0 145 L120 120 L240 132 L360 80 L480 92 L620 30"/><g>{[[0,145],[120,120],[240,132],[360,80],[480,92],[620,30]].map(([x,y])=><circle key={x} cx={x} cy={y} r="5"/>)}</g></svg><div className="chart-labels"><span>MAR</span><span>ABR</span><span>MAI</span><span>JUN</span><span>JUL</span><span>AGORA</span></div></div></section>
          <aside className="achievement-panel"><div className="dash-section-title"><div><p>CONQUISTA RECENTE</p><h2>Missão cumprida</h2></div></div><div className="medal-mark"><Target/></div><strong>Especialista em objetivos</strong><p>Complete 25 objetivos confirmados em operações oficiais.</p><div><span>RARIDADE</span><b>RARA</b><small>Desbloqueada há 2 dias</small></div></aside>
        </div>
        <p className="dashboard-disclaimer"><ShieldCheck/> Ambiente demonstrativo — todos os nomes, pontos e atividades exibidos nesta tela são dados fictícios.</p>
      </main>}
    </div>
    <nav className="mobile-app-nav" aria-label="Navegação mobile">{dashboardNav.filter(item => ['Visão geral','Operações','Rankings','Comunidade','Conquistas','Meu Operador'].includes(item.label)).map(({label,icon:Icon}) => <button onClick={() => setActiveView(label)} className={activeView===label?'active':''} key={label}><Icon/><span>{label}</span></button>)}</nav>
  </div>
}

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false)
  const [authMode, setAuthMode] = useState<AuthMode | null>(null)
  const [demoSession, setDemoSession] = useState(false)
  useEffect(() => {
    const close = () => setMenuOpen(false)
    window.addEventListener('resize', close)
    return () => window.removeEventListener('resize', close)
  }, [])

  if (demoSession) return <Dashboard onLogout={() => setDemoSession(false)}/>

  const authenticateDemo = () => { setAuthMode(null); setDemoSession(true) }
  const nav = ['Operações', 'Campos', 'Equipes', 'Rankings']
  return <div className="site-shell">
    <header className="topbar">
      <Brand compact />
      <nav className="desktop-nav" aria-label="Navegação principal">{nav.map(item => <a key={item} href={`#${item.toLowerCase().replace('ç','c').replace('õ','o')}`}>{item}</a>)}</nav>
      <div className="header-actions"><button className="text-button" onClick={() => setAuthMode('login')}>Entrar</button><button className="button button--small" onClick={() => setAuthMode('signup')}>Criar conta</button></div>
      <button className="menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-expanded={menuOpen} aria-label="Abrir menu">{menuOpen ? <X /> : <Menu />}</button>
      {menuOpen && <div className="mobile-menu">{nav.map(item => <a key={item} onClick={() => setMenuOpen(false)} href={`#${item.toLowerCase().replace('ç','c').replace('õ','o')}`}>{item}</a>)}<button onClick={() => { setMenuOpen(false); setAuthMode('signup') }}>Criar conta</button><button onClick={() => { setMenuOpen(false); setAuthMode('login') }}>Entrar</button></div>}
    </header>

    <main>
      <section className="hero" id="inicio">
        <div className="hero-art" aria-hidden="true"><img src="/operador-zero-identity.jpeg" alt="" /></div>
        <div className="hero-shade" />
        <div className="hero-content">
          <p className="eyebrow reveal reveal--1"><span /> A plataforma do airsoft brasileiro</p>
          <h1 className="reveal reveal--2">Sua próxima<br/><em>operação</em> começa aqui.</h1>
          <p className="hero-copy reveal reveal--3">Encontre partidas, fortaleça sua equipe e construa um histórico esportivo que representa sua evolução.</p>
          <div className="hero-actions reveal reveal--4"><a className="button" href="#operacoes">Explorar operações <ArrowRight size={18}/></a><a className="link-button" href="#como-funciona">Como funciona <ChevronDown size={17}/></a></div>
        </div>
        <div className="hero-index"><span>01</span><i/><small>PLATAFORMA ESPORTIVA</small></div>
      </section>

      <section className="operations section" id="operacoes">
        <div className="section-heading"><div><p className="eyebrow"><span/> Agenda ativa</p><h2>Próximas operações</h2></div><a href="#operacoes">Ver agenda completa <ArrowRight size={17}/></a></div>
        <div className="operation-list">{operations.map((op, index) => <article className="operation-row" key={op.title}>
          <div className="date"><strong>{op.day}</strong><span>{op.month}</span></div>
          <div className="op-title"><small>0{index + 1} / OPERAÇÃO</small><h3>{op.title}</h3></div>
          <p><MapPin size={16}/>{op.meta}</p><span className="mode">{op.mode}</span><span className="slots">{op.slots}</span><button aria-label={`Abrir ${op.title}`}><ArrowRight/></button>
        </article>)}</div>
      </section>

      <section className="manifesto" id="como-funciona">
        <div className="manifesto-copy"><p className="eyebrow"><span/> Histórico confiável</p><h2>Jogue. Registre.<br/><em>Ran­queie.</em> Evolua.</h2><p>O Operador Zero conecta sua jornada — da confirmação na partida ao resultado validado. Sua evolução considera presença, objetivos, desempenho, consistência e reputação.</p><a href="#metodo">Conheça nosso método <ArrowRight size={17}/></a></div>
        <div className="steps" id="metodo">
          <div><CalendarDays/><span>01</span><div className="step-content"><h3>Encontre</h3><p>Descubra operações por cidade, modalidade e data.</p></div></div>
          <div><ShieldCheck/><span>02</span><div className="step-content"><h3>Confirme</h3><p>Participe e valide registros com equipe e organização.</p></div></div>
          <div><Trophy/><span>03</span><div className="step-content"><h3>Evolua</h3><p>Construa reputação, conquistas e posição no ranking.</p></div></div>
        </div>
      </section>

      <section className="ranking section" id="rankings">
        <div className="section-heading"><div><p className="eyebrow"><span/> Temporada 2026</p><h2>Ranking em movimento</h2></div><div className="filters"><button className="active">Operadores</button><button>Equipes</button><button>Paraná</button></div></div>
        <div className="ranking-table"><div className="table-head"><span>Pos.</span><span>Operador</span><span>Equipe</span><span>Pontos</span><span>Variação</span></div>{ranking.map(player => <div className="rank-row" key={player.position}><strong>{player.position}</strong><div className="avatar">{player.callsign[0]}</div><b>{player.callsign}</b><span>{player.team}</span><strong>{player.score}</strong><i className={player.delta.startsWith('-') ? 'down' : ''}>{player.delta}</i></div>)}</div>
        <p className="demo-note">Dados demonstrativos para visualização da experiência inicial.</p>
      </section>

      <section className="community" id="equipes"><div><Users/><p className="eyebrow">Um só ecossistema</p><h2>Operadores, equipes, campos e organizadores.</h2><p>Perfis públicos, eventos, campeonatos e estatísticas validadas em uma comunidade criada para o esporte.</p></div></section>

      <section className="cta" id="convite"><p className="eyebrow"><span/> Prepare seu callsign</p><h2>Entre para a<br/>próxima operação.</h2><p>Crie seu perfil com Google ou e-mail e senha.</p><button className="button" onClick={() => setAuthMode('signup')}>Criar minha conta <ArrowRight size={18}/></button></section>
    </main>
    <footer><Brand compact/><p>Airsoft é esporte. Respeito, segurança e fair play sempre.</p><div><a href="#inicio">Termos</a><a href="#inicio">Privacidade</a><a href="#inicio">Segurança</a></div><small>© 2026 OPERADOR ZERO</small></footer>
    {authMode && <AuthModal mode={authMode} onClose={() => setAuthMode(null)} onModeChange={setAuthMode} onAuthenticated={authenticateDemo}/>} 
  </div>
}
